import { defineConfig } from 'vite'

export default defineConfig({
  base: './',
  server: { host: '0.0.0.0', port: 3002 },
  build: { target: 'es2020', chunkSizeWarningLimit: 1600 }
})

:root{
  --navy:#070d18;
  --panel:rgba(8,18,32,.82);
  --panel-2:rgba(12,26,44,.92);
  --line:rgba(120,200,255,.28);
  --cyan:#7fd9ff;
  --cyan-soft:#a8e9ff;
  --green:#46e07c;
  --green-2:#0f9d4b;
  --blue:#48a7ff;
  --orange:#ffb347;
  --red:#ff5a5a;
  --text:#e8f4ff;
  --muted:#8fa8c0;
  --safe-t:env(safe-area-inset-top,0px);
  --safe-b:env(safe-area-inset-bottom,0px);
  --safe-l:env(safe-area-inset-left,0px);
  --safe-r:env(safe-area-inset-right,0px);
  --ui:'Segoe UI',system-ui,-apple-system,'Helvetica Neue',Arial,sans-serif;
}
*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{width:100%;height:100%;overflow:hidden;background:#050a12;color:var(--text);font-family:var(--ui);overscroll-behavior:none;touch-action:none}
body{position:fixed;inset:0}
#app{position:absolute;inset:0;overflow:hidden;background:#050a12}
#scene{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}
#vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 46%,transparent 42%,rgba(2,6,14,.38) 100%);z-index:2}
.hidden{display:none!important}
button{font-family:var(--ui);cursor:pointer;border:none;background:none;color:inherit}

/* ---------- HUD ---------- */
#hud{position:absolute;inset:0;z-index:5;pointer-events:none;opacity:1;transition:opacity .4s}
#hud.hidden{display:none}
#hud::before{content:"";position:absolute;left:0;top:0;right:0;height:130px;background:linear-gradient(180deg,rgba(3,8,16,.55),transparent);pointer-events:none}
.hud-bars{position:absolute;top:calc(var(--safe-t) + 14px);left:calc(var(--safe-l) + 16px);width:min(340px,42vw);filter:drop-shadow(0 2px 6px rgba(0,0,0,.6))}
.name-row{display:flex;align-items:baseline;gap:8px;margin-bottom:5px}
.player-name{font-size:15px;letter-spacing:3.5px;font-weight:700;color:#fff;text-shadow:0 0 10px rgba(140,220,255,.6)}
.player-level{font-size:11px;letter-spacing:1px;color:var(--cyan);border:1px solid var(--line);padding:1px 6px;border-radius:2px;background:rgba(10,25,45,.65)}
.player-class{font-size:8px;letter-spacing:2px;color:var(--muted);margin-left:auto;white-space:nowrap}
.bar{position:relative;height:11px;margin-bottom:4px;background:rgba(2,10,20,.78);border:1px solid rgba(170,225,255,.4);border-radius:1px;overflow:hidden;clip-path:polygon(0 0,100% 0,calc(100% - 6px) 100%,0 100%)}
.bar-fill{position:absolute;inset:1px;width:100%;transform-origin:left;transition:width .22s ease-out;border-radius:1px}
.hp-bar .bar-fill{background:linear-gradient(90deg,#0e7a3d,#33d26d 45%,#8bffad 75%,#3fd57a);box-shadow:0 0 12px rgba(70,224,124,.55)}
.mp-bar{height:7px}
.mp-bar .bar-fill{background:linear-gradient(90deg,#1d5fa8,#4fb6ff 70%,#b9ecff);box-shadow:0 0 10px rgba(72,167,255,.5)}
.stam-bar{height:4px;border-color:rgba(255,220,140,.25);width:62%;margin-top:2px}
.stam-bar .bar-fill{background:linear-gradient(90deg,#8a6420,#ffd36b);opacity:.9}
.bar-gloss{position:absolute;inset:0;background:linear-gradient(180deg,rgba(255,255,255,.34),transparent 50%,rgba(0,0,0,.18));pointer-events:none}
.bar-label{position:absolute;right:10px;top:50%;transform:translateY(-50%);font-size:8px;letter-spacing:.6px;font-weight:700;color:rgba(240,255,250,.92);text-shadow:0 1px 2px #000;line-height:1}
.mp-bar .bar-label{font-size:6.5px;color:#dff3ff}
.hud-bars::after{content:"";display:block;height:1px;width:70%;margin-top:4px;background:linear-gradient(90deg,rgba(127,217,255,.5),transparent)}

#zone-banner{position:absolute;top:calc(var(--safe-t) + 16px);left:50%;transform:translateX(-50%);text-align:center;opacity:0;transition:opacity .8s;pointer-events:none}
#zone-banner.show{opacity:1}
.zone-sub{display:block;font-size:8px;letter-spacing:4px;color:rgba(180,225,255,.7)}
.zone-name{display:block;font-size:15px;letter-spacing:5px;font-weight:600;color:#fff;text-shadow:0 0 18px rgba(120,210,255,.8),0 2px 4px #000;margin-top:2px}

.minimap-wrap{position:absolute;top:calc(var(--safe-t) + 10px);right:calc(var(--safe-r) + 14px);width:clamp(86px,15vw,116px);height:clamp(86px,15vw,116px);border-radius:50%;overflow:hidden;border:1px solid rgba(150,220,255,.5);box-shadow:0 0 22px rgba(0,0,0,.55),inset 0 0 18px rgba(40,120,180,.25);background:rgba(6,18,30,.8)}
#minimap{width:100%;height:100%;display:block}
.minimap-ring{position:absolute;inset:4px;border-radius:50%;border:1px solid rgba(150,225,255,.22)}
.compass-n{position:absolute;top:2px;left:50%;transform:translateX(-50%);font-size:7px;color:var(--cyan);letter-spacing:1px;text-shadow:0 0 4px #000}

#quest-tracker{position:absolute;top:calc(var(--safe-t) + 140px);right:calc(var(--safe-r) + 16px);width:min(230px,30vw);padding:9px 11px 10px;background:linear-gradient(135deg,rgba(8,22,38,.82),rgba(8,18,30,.5));border-left:2px solid var(--orange);backdrop-filter:blur(4px);clip-path:polygon(0 0,100% 0,100% calc(100% - 10px),calc(100% - 10px) 100%,0 100%)}
.quest-head{font-size:7.5px;letter-spacing:3px;color:var(--orange);display:flex;align-items:center;gap:5px}
.quest-diamond{font-size:8px;text-shadow:0 0 6px rgba(255,179,71,.8)}
.quest-title{font-size:12px;font-weight:600;letter-spacing:.6px;color:#fff;margin-top:4px;line-height:1.25}
.quest-objective{font-size:10px;color:#b9cfe4;margin-top:3px;letter-spacing:.2px}
.quest-objective b{color:var(--orange);font-weight:700}
.quest-objective.done{color:var(--green)}
.quest-objective.done b{color:var(--green)}

.hud-bottom-left{position:absolute;left:calc(var(--safe-l) + 16px);bottom:calc(var(--safe-b) + 16px);width:min(240px,36vw)}
#col-display{font-size:12px;letter-spacing:1.5px;color:var(--orange);margin-bottom:5px;text-shadow:0 1px 4px #000}
.col-icon{color:#ffd166;text-shadow:0 0 8px rgba(255,209,102,.7);margin-right:3px}
#col-display b{font-size:15px;color:#fff}
.col-unit{font-size:7px;letter-spacing:2px;color:rgba(255,209,102,.7)}
#xp-strip{position:relative;height:9px;border:1px solid rgba(127,217,255,.28);background:rgba(2,10,20,.7);overflow:hidden;clip-path:polygon(0 0,100% 0,100% 100%,5px 100%)}
#xp-fill{height:100%;width:0%;background:linear-gradient(90deg,rgba(72,167,255,.4),var(--cyan));box-shadow:0 0 8px rgba(127,217,255,.5);transition:width .4s}
#xp-label{position:absolute;inset:0;font-size:6.5px;letter-spacing:1.4px;display:flex;align-items:center;justify-content:center;color:#eaf7ff;text-shadow:0 1px 2px #000}

#interact-prompt{position:absolute;left:50%;bottom:calc(var(--safe-b) + 23%);transform:translateX(-50%);background:rgba(6,16,28,.82);border:1px solid var(--line);padding:7px 14px 7px 8px;display:flex;align-items:center;gap:8px;font-size:11px;letter-spacing:1px;color:#fff;backdrop-filter:blur(4px);animation:pulsePrompt 1.6s ease-in-out infinite;white-space:nowrap}
#interact-prompt .key{display:inline-flex;align-items:center;justify-content:center;min-width:20px;height:20px;background:linear-gradient(180deg,#dff4ff,#9dc9e8);color:#07131f;font-weight:800;font-size:10px;border-radius:2px}
@keyframes pulsePrompt{0%,100%{box-shadow:0 0 0 0 rgba(127,217,255,.25)}50%{box-shadow:0 0 22px 2px rgba(127,217,255,.28)}}

#combo-display{position:absolute;right:calc(var(--safe-r) + 5vw);top:38%;display:flex;align-items:center;gap:6px;transform:rotate(-4deg);text-shadow:0 0 14px rgba(255,179,71,.8),0 2px 4px #000}
#combo-num{font-size:40px;font-weight:800;font-style:italic;color:#fff;line-height:.8;letter-spacing:-2px}
.combo-label{font-size:8px;letter-spacing:2px;line-height:1.4;color:var(--orange);font-weight:700}

#toasts{position:absolute;left:50%;top:26%;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:8px;width:min(420px,80vw)}
.toast{padding:8px 18px;font-size:11px;letter-spacing:1.6px;color:#fff;background:linear-gradient(90deg,transparent,rgba(8,24,40,.86) 15%,rgba(8,24,40,.86) 85%,transparent);border-top:1px solid rgba(127,217,255,.35);border-bottom:1px solid rgba(127,217,255,.2);animation:toastIn .35s ease-out;white-space:nowrap;text-align:center}
.toast.reward{color:#ffe1a6;border-color:rgba(255,179,71,.45)}
.toast.level{color:#9dffbe;border-color:rgba(70,224,124,.5);font-size:13px;text-shadow:0 0 12px rgba(70,224,124,.6)}
.toast.quest{color:#bfe9ff}
.toast.fade{opacity:0;transform:translateY(-8px);transition:opacity .5s,transform .5s}
@keyframes toastIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}

#damage-layer{position:absolute;inset:0;z-index:6;pointer-events:none;overflow:hidden}
.dmg{position:absolute;font-weight:800;font-style:italic;font-size:17px;color:#fff;text-shadow:0 0 6px rgba(0,0,0,.9),0 2px 3px #000;will-change:transform,opacity;animation:dmgFloat .85s ease-out forwards;letter-spacing:-.5px}
.dmg.crit{font-size:24px;color:#ffd166;text-shadow:0 0 10px rgba(255,140,40,.9),0 2px 3px #000}
.dmg.player{color:#ff7878;font-size:19px}
.dmg.heal{color:#7dffa6}
@keyframes dmgFloat{0%{opacity:0;transform:translate(-50%,0) scale(.6)}18%{opacity:1;transform:translate(-50%,-14px) scale(1.18)}100%{opacity:0;transform:translate(-50%,-52px) scale(.95)}}

