export const TAU = Math.PI * 2
export const clamp = (v, a, b) => Math.min(b, Math.max(a, v))
export const lerp = (a, b, t) => a + (b - a) * t
export const invLerp = (a, b, v) => (v - a) / (b - a)
export const smoothstep = (e0, e1, x) => {
  const t = clamp((x - e0) / (e1 - e0), 0, 1)
  return t * t * (3 - 2 * t)
}
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt))
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a)
export const randInt = (a, b) => Math.floor(rand(a, b + 1))
export const pick = arr => arr[Math.floor(Math.random() * arr.length)]
export const dist2 = (ax, az, bx, bz) => Math.hypot(ax - bx, az - bz)

export function angleDelta(a, b) {
  let d = (b - a) % TAU
  if (d > Math.PI) d -= TAU
  if (d < -Math.PI) d += TAU
  return d
}
export function angleLerp(a, b, t) {
  return a + angleDelta(a, b) * t
}
export function dampAngle(a, b, lambda, dt) {
  return angleLerp(a, b, 1 - Math.exp(-lambda * dt))
}

export function mulberry32(seed) {
  let a = seed >>> 0
  return function () {
    a |= 0
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

export function projectToScreen(vec3, camera, width, height) {
  const v = vec3.clone().project(camera)
  return {
    x: (v.x * 0.5 + 0.5) * width,
    y: (-v.y * 0.5 + 0.5) * height,
    visible: v.z < 1 && v.z > -1
  }
}

export function formatNum(n) {
  return Math.max(0, Math.round(n)).toLocaleString('en-US')
}

import * as THREE from 'three'
import { clamp, lerp, smoothstep, mulberry32 } from './utils.js'

export const WORLD_SIZE = 430
export const WORLD_RADIUS = 205
export const WATER_Y = 0.7

export const TOWN = { x: 0, z: 0, r: 34 }
export const LAKE = { x: 104, z: 54, r: 34 }
export const RUINS = { x: -86, z: -46, r: 26 }

function baseHills(x, z) {
  return (
    Math.sin(x * 0.045) * Math.cos(z * 0.038) * 4.4 +
    Math.sin(x * 0.103 + 1.7) * Math.sin(z * 0.077 - 0.4) * 2.2 +
    Math.cos(x * 0.21 + z * 0.16) * 0.75 +
    Math.sin(x * 0.017 - z * 0.021) * 2.6
  )
}

export function heightAt(x, z) {
  const d = Math.hypot(x, z)
  let h = 3.0 + baseHills(x, z)

  // Flat plaza around the Town of Beginnings.
  const townT = smoothstep(TOWN.r + 4, TOWN.r + 34, d)
  h = lerp(3.05, h, townT)

  // Ragged mountain ring keeps the world feeling enclosed.
  const m = smoothstep(148, 208, d)
  h += m * m * 46 + m * 9

  // Mirror Lake basin.
  const lakeD = Math.hypot(x - LAKE.x, z - LAKE.z)
  const lakeT = 1 - smoothstep(LAKE.r * 0.45, LAKE.r, lakeD)
  h -= 8.2 * lakeT

  // Raised ruin plateau.
  const ruinD = Math.hypot(x - RUINS.x, z - RUINS.z)
  const ruinT = 1 - smoothstep(RUINS.r * 0.55, RUINS.r + 8, ruinD)
  h = lerp(h, 7.2, ruinT * 0.85)

  return h
}

export function slopeAt(x, z) {
  const e = 0.9
  const hx = heightAt(x + e, z) - heightAt(x - e, z)
  const hz = heightAt(x, z + e) - heightAt(x, z - e)
  return Math.hypot(hx, hz) / (2 * e)
}

// Roads: town gate -> north plains, town -> forest, town -> ruin ridge.
const ROADS = [
  [[0, -8], [-4, -40], [2, -80], [10, -118]],
  [[8, 4], [38, 6], [58, -10], [78, -4]],
  [[-8, -4], [-32, -16], [-56, -26], [-75, -40]]
]

function distToSegment(px, pz, ax, az, bx, bz) {
  const dx = bx - ax, dz = bz - az
  const t = clamp(((px - ax) * dx + (pz - az) * dz) / (dx * dx + dz * dz), 0, 1)
  return Math.hypot(px - (ax + dx * t), pz - (az + dz * t))
}

export function pathDistance(x, z) {
  let best = 999
  for (const road of ROADS) {
    for (let i = 0; i < road.length - 1; i++) {
      const d = distToSegment(x, z, road[i][0], road[i][1], road[i + 1][0], road[i + 1][1])
      if (d < best) best = d
    }
  }
  return best
}

export function isOnPath(x, z) {
  return pathDistance(x, z) < 2.4
}

const C_GRASS_A = new THREE.Color('#4d7c36')
const C_GRASS_B = new THREE.Color('#699645')
const C_GRASS_C = new THREE.Color('#3d6630')
const C_DIRT = new THREE.Color('#9c7d52')
const C_ROCK = new THREE.Color('#797c70')
const C_SAND = new THREE.Color('#b7a170')
const C_TOWN = new THREE.Color('#8d8a76')

export function createTerrain() {
  const seg = 176
  const geo = new THREE.PlaneGeometry(WORLD_SIZE, WORLD_SIZE, seg, seg)
  geo.rotateX(-Math.PI / 2)
  const pos = geo.attributes.position
  const colors = new Float32Array(pos.count * 3)
  const rng = mulberry32(9137)
  const col = new THREE.Color()
  const grass = new THREE.Color()

  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i)
    const z = pos.getZ(i)
    const y = heightAt(x, z)
    pos.setY(i, y)

    const slope = slopeAt(x, z)
    const n = Math.sin(x * 0.42 + z * 0.31) * 0.5 + Math.sin(x * 0.17 - z * 0.23) * 0.5
    grass.copy(C_GRASS_A).lerp(C_GRASS_B, 0.5 + n * 0.35).lerp(C_GRASS_C, Math.max(0, -n) * 0.3)

    const townD = Math.hypot(x, z)
    const lakeD = Math.hypot(x - LAKE.x, z - LAKE.z)
    const roadD = pathDistance(x, z)

    if (townD < TOWN.r + 2) grass.lerp(C_TOWN, 0.35)
    if (lakeD < LAKE.r + 3) {
      const shore = 1 - smoothstep(LAKE.r - 9, LAKE.r + 2, lakeD)
      grass.lerp(C_SAND, shore * 0.85)
    }
    if (roadD < 2.6) grass.lerp(C_DIRT, (1 - roadD / 2.6) * 0.8)
    if (slope > 0.42) grass.lerp(C_ROCK, smoothstep(0.42, 0.95, slope) * 0.85)

    col.copy(grass).multiplyScalar(0.93 + rng() * 0.14)
    colors[i * 3] = col.r
    colors[i * 3 + 1] = col.g
    colors[i * 3 + 2] = col.b
  }

  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3))
  geo.computeVertexNormals()

  const mat = new THREE.MeshStandardMaterial({
    vertexColors: true,
    roughness: 0.95,
    metalness: 0.0
  })
  const mesh = new THREE.Mesh(geo, mat)
  mesh.receiveShadow = true
  mesh.name = 'terrain'
  return mesh
}

export function createWater() {
  const geo = new THREE.PlaneGeometry(96, 96, 40, 40)
  geo.rotateX(-Math.PI / 2)
  const pos = geo.attributes.position
  const base = Float32Array.from(pos.array)
  const mat = new THREE.MeshStandardMaterial({
    color: '#2f7691',
    roughness: 0.16,
    metalness: 0.35,
    transparent: true,
    opacity: 0.82
  })
  const mesh = new THREE.Mesh(geo, mat)
  mesh.position.set(LAKE.x, WATER_Y, LAKE.z)
  mesh.receiveShadow = true
  mesh.userData.update = t => {
    for (let i = 0; i < pos.count; i++) {
      const x = base[i * 3]
      const z = base[i * 3 + 2]
      pos.setY(i, Math.sin(x * 0.45 + t * 1.1) * 0.16 + Math.cos(z * 0.38 - t * 0.85) * 0.14)
    }
    pos.needsUpdate = true
  }
  return mesh
}

export function zoneAt(x, z) {
  const townD = Math.hypot(x, z)
  if (townD < TOWN.r + 6) return { name: 'TOWN OF BEGINNINGS', sub: 'AINCRAD · FLOOR 1' }
  const lakeD = Math.hypot(x - LAKE.x, z - LAKE.z)
  if (lakeD < LAKE.r + 12) return { name: 'MIRROR LAKE', sub: 'AINCRAD · FLOOR 1' }
  const ruinD = Math.hypot(x - RUINS.x, z - RUINS.z)
  if (ruinD < RUINS.r + 24) return { name: 'KOBOLD RUINS', sub: 'AINCRAD · FLOOR 1' }
  if (x > 40) return { name: 'WOLFPINE FOREST', sub: 'AINCRAD · FLOOR 1' }
  if (z < -25) return { name: 'BEGINNING PLAINS', sub: 'AINCRAD · FLOOR 1' }
  if (townD > 150) return { name: 'AINCRAD HIGHLANDS', sub: 'AINCRAD · FLOOR 1' }
  return { name: 'BEGINNING PLAINS', sub: 'AINCRAD · FLOOR 1' }
}

import * as THREE from 'three'

export const SUN_DIR = new THREE.Vector3(-0.52, 0.34, -0.78).normalize()

const skyVert = /* glsl */`
  varying vec3 vDir;
  void main() {
    vDir = normalize(position);
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_Position = projectionMatrix * mv;
  }
`

const skyFrag = /* glsl */`
  precision highp float;
  varying vec3 vDir;
  uniform vec3 sunDir;
  uniform float time;

  float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
  }
  float noise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);
  }
  float fbm(vec2 p) {
    float v = 0.0, a = 0.5;
    for (int i = 0; i < 4; i++) { v += a * noise(p); p *= 2.04; a *= 0.5; }
    return v;
  }

  void main() {
    vec3 d = normalize(vDir);
    float up = clamp(d.y, 0.0, 1.0);

    vec3 zenith = vec3(0.17, 0.40, 0.68);
    vec3 mid = vec3(0.42, 0.66, 0.86);
    vec3 horizon = vec3(0.98, 0.78, 0.56);
    vec3 low = vec3(0.92, 0.68, 0.48);

    vec3 col = mix(mid, zenith, pow(up, 0.62));
    col = mix(horizon, col, smoothstep(0.0, 0.30, d.y));
    col = mix(low, col, smoothstep(-0.12, 0.06, d.y));

    float sd = max(dot(d, sunDir), 0.0);
    col += vec3(1.0, 0.60, 0.26) * pow(sd, 6.0) * 0.42;
    col += vec3(1.0, 0.80, 0.48) * pow(sd, 42.0) * 0.65;
    col += vec3(1.0, 0.94, 0.82) * pow(sd, 1400.0) * 9.0;

    // Soft billowing clouds projected on the sky dome.
    if (d.y > 0.015) {
      vec2 p = d.xz / (d.y + 0.22) * 1.15;
      p += vec2(time * 0.004, time * 0.0016);
      float c = fbm(p * 1.25);
      c = smoothstep(0.50, 0.82, c);
      float fade = smoothstep(0.015, 0.22, d.y) * (1.0 - smoothstep(0.55, 0.95, d.y) * 0.45);
      vec3 cloudLight = mix(vec3(1.0, 0.86, 0.72), vec3(1.0, 0.98, 0.94), smoothstep(0.0, 0.35, d.y));
      vec3 cloudShade = vec3(0.72, 0.66, 0.70);
      vec3 cloudCol = mix(cloudShade, cloudLight, smoothstep(0.5, 0.9, fbm(p * 1.25 + 0.35)));
      col = mix(col, cloudCol, c * fade * 0.88);
    }

    // Warm haze where the sky meets the mountains.
    float haze = pow(1.0 - abs(d.y), 9.0);
    col = mix(col, vec3(0.99, 0.82, 0.64), haze * 0.55);

    gl_FragColor = vec4(col, 1.0);
  }
`

export function createSky() {
  const geo = new THREE.SphereGeometry(880, 40, 24)
  const mat = new THREE.ShaderMaterial({
    vertexShader: skyVert,
    fragmentShader: skyFrag,
    uniforms: {
      sunDir: { value: SUN_DIR.clone() },
      time: { value: 0 }
    },
    side: THREE.BackSide,
    depthWrite: false,
    fog: false
  })
  const mesh = new THREE.Mesh(geo, mat)
  mesh.frustumCulled = false
  mesh.renderOrder = -100
  mesh.userData.update = t => { mat.uniforms.time.value = t }
  return mesh
}

export function createSunLight() {
  const sun = new THREE.DirectionalLight('#ffe2b8', 2.15)
  sun.position.copy(SUN_DIR).multiplyScalar(120)
  sun.castShadow = true
  sun.shadow.mapSize.set(2048, 2048)
  sun.shadow.camera.near = 1
  sun.shadow.camera.far = 300
  const s = 52
  sun.shadow.camera.left = -s
  sun.shadow.camera.right = s
  sun.shadow.camera.top = s
  sun.shadow.camera.bottom = -s
  sun.shadow.bias = -0.0009
  sun.shadow.normalBias = 0.035
  return sun
}

export function createFillLight() {
  const fill = new THREE.DirectionalLight('#b7d6ff', 0.55)
  fill.position.set(60, 42, 90)
  return fill
}

function rockMat(color = '#5e5a63') {
  return new THREE.MeshStandardMaterial({ color, roughness: 1, metalness: 0, flatShading: true, fog: false })
}

export function createAincrad() {
  const root = new THREE.Group()
  root.position.set(-96, 104, -392)
  root.rotation.y = 0.35
  root.scale.setScalar(2.15)

  const stone = rockMat('#6b6470')
  const stoneDark = rockMat('#4a4552')
  const grass = new THREE.MeshStandardMaterial({ color: '#4f7a46', roughness: 1, flatShading: true, fog: false })
  const roof = new THREE.MeshStandardMaterial({ color: '#33465e', roughness: 0.9, flatShading: true, fog: false })
  const glow = new THREE.MeshBasicMaterial({ color: '#8fe3ff', fog: false })

  // Main floating island
  const island = new THREE.Mesh(new THREE.CylinderGeometry(30, 3, 34, 9, 1), stoneDark)
  island.position.y = -17
  root.add(island)

  const top = new THREE.Mesh(new THREE.CylinderGeometry(30, 27, 5, 9), grass)
  top.position.y = 2
  root.add(top)

  const rim = new THREE.Mesh(new THREE.TorusGeometry(29.2, 1.1, 4, 9), stone)
  rim.rotation.x = Math.PI / 2
  rim.position.y = 4.6
  root.add(rim)

  // Central spire + disk floors
  const spire = new THREE.Mesh(new THREE.CylinderGeometry(3.1, 5.2, 62, 8), stone)
  spire.position.y = 36
  root.add(spire)
  const spireTop = new THREE.Mesh(new THREE.ConeGeometry(4.6, 12, 8), roof)
  spireTop.position.y = 73
  root.add(spireTop)

  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2
    const ring = new THREE.Mesh(new THREE.CylinderGeometry(7.4, 5.6, 2.4, 12), stone)
    ring.position.set(Math.cos(a) * 15, 10 + i * 7.2, Math.sin(a) * 15)
    root.add(ring)

    const tower = new THREE.Mesh(new THREE.CylinderGeometry(2.0, 2.8, 16, 6), stone)
    tower.position.set(Math.cos(a) * 15, 19 + i * 7.2, Math.sin(a) * 15)
    root.add(tower)

    const cap = new THREE.Mesh(new THREE.ConeGeometry(3.1, 7, 6), roof)
    cap.position.set(Math.cos(a) * 15, 30 + i * 7.2, Math.sin(a) * 15)
    root.add(cap)

    const light = new THREE.Mesh(new THREE.BoxGeometry(0.65, 1.1, 0.65), glow)
    light.position.set(Math.cos(a) * 15, 16 + i * 7.2, Math.sin(a) * 15)
    root.add(light)
  }

  // Outer curtain walls
  for (let i = 0; i < 14; i++) {
    const a = (i / 14) * Math.PI * 2
    const pillar = new THREE.Mesh(new THREE.BoxGeometry(2.4, 7.5, 2.4), stone)
    pillar.position.set(Math.cos(a) * 26, 8.2, Math.sin(a) * 26)
    pillar.rotation.y = -a
    root.add(pillar)
  }

  // Hanging gardens / floating satellites
  const satellites = [
    { p: [44, 30, 8], s: 5.2 },
    { p: [-38, 52, -14], s: 3.8 },
    { p: [20, 68, -24], s: 2.8 },
    { p: [-52, 12, 20], s: 4.4 }
  ]
  for (const sat of satellites) {
    const g = new THREE.Group()
    g.position.set(...sat.p)
    const base = new THREE.Mesh(new THREE.ConeGeometry(sat.s, sat.s * 2.1, 7), stoneDark)
    base.rotation.x = Math.PI
    base.position.y = -sat.s
    g.add(base)
    const disc = new THREE.Mesh(new THREE.CylinderGeometry(sat.s, sat.s * 0.92, 1.2, 8), grass)
    g.add(disc)
    const shard = new THREE.Mesh(new THREE.OctahedronGeometry(1.1, 0), glow)
    shard.position.y = sat.s + 1.6
    shard.scale.y = 2.4
    g.add(shard)
    root.add(g)
  }

  // Distant glow behind the castle
  const canvas = document.createElement('canvas')
  canvas.width = canvas.height = 128
  const ctx = canvas.getContext('2d')
  const grad = ctx.createRadialGradient(64, 64, 0, 64, 64, 64)
  grad.addColorStop(0, 'rgba(160,220,255,0.55)')
  grad.addColorStop(0.4, 'rgba(120,190,255,0.18)')
  grad.addColorStop(1, 'rgba(120,190,255,0)')
  ctx.fillStyle = grad
  ctx.fillRect(0, 0, 128, 128)
  const tex = new THREE.CanvasTexture(canvas)
  const glowSprite = new THREE.Sprite(new THREE.SpriteMaterial({
    map: tex, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, fog: false, opacity: 0.8
  }))
  glowSprite.scale.set(130, 130, 1)
  glowSprite.position.y = 34
  root.add(glowSprite)

  return root
}

import * as THREE from 'three'
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js'
import { heightAt, pathDistance, TOWN, LAKE, RUINS, WATER_Y } from './terrain.js'
import { mulberry32, smoothstep, TAU } from './utils.js'

const _m = new THREE.Matrix4()
const _q = new THREE.Quaternion()
const _e = new THREE.Euler()
const _s = new THREE.Vector3()
const _p = new THREE.Vector3()
const _c = new THREE.Color()

class GeoBatch {
  constructor() { this.parts = [] }
  add(geo, color, x = 0, y = 0, z = 0, ry = 0, rx = 0, rz = 0, sx = 1, sy = 1, sz = 1) {
    const g = geo.clone()
    _e.set(rx, ry, rz)
    _q.setFromEuler(_e)
    _m.compose(_p.set(x, y, z), _q, _s.set(sx, sy, sz))
    g.applyMatrix4(_m)
    _c.set(color)
    const count = g.attributes.position.count
    const arr = new Float32Array(count * 3)
    for (let i = 0; i < count; i++) {
      arr[i * 3] = _c.r
      arr[i * 3 + 1] = _c.g
      arr[i * 3 + 2] = _c.b
    }
    g.setAttribute('color', new THREE.BufferAttribute(arr, 3))
    if (g.attributes.uv) g.deleteAttribute('uv')
    this.parts.push(g)
    return this
  }
  mesh(material) {
    if (!this.parts.length) return null
    const merged = mergeGeometries(this.parts, false)
    const mesh = new THREE.Mesh(merged, material)
    mesh.castShadow = true
    mesh.receiveShadow = true
    return mesh
  }
}

function box(w, h, d) { return new THREE.BoxGeometry(w, h, d) }

function makeSignTexture(main, sub) {
  const canvas = document.createElement('canvas')
  canvas.width = 512
  canvas.height = 140
  const ctx = canvas.getContext('2d')
  const grad = ctx.createLinearGradient(0, 0, 0, 140)
  grad.addColorStop(0, '#1a2a3d')
  grad.addColorStop(1, '#0a1523')
  ctx.fillStyle = grad
  ctx.fillRect(0, 0, 512, 140)
  ctx.strokeStyle = 'rgba(160,220,255,0.55)'
  ctx.lineWidth = 3
  ctx.strokeRect(6, 6, 500, 128)
  ctx.strokeStyle = 'rgba(160,220,255,0.18)'
  ctx.lineWidth = 1
  ctx.strokeRect(14, 14, 484, 112)
  ctx.fillStyle = '#eaf8ff'
  ctx.font = '600 34px Segoe UI, Arial, sans-serif'
  ctx.textAlign = 'center'
  ctx.textBaseline = 'middle'
  ctx.fillText(main, 256, 58)
  ctx.fillStyle = 'rgba(150,215,255,0.75)'
  ctx.font = '18px Segoe UI, Arial, sans-serif'
  ctx.fillText(sub, 256, 100)
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

function makeBannerTexture() {
  const canvas = document.createElement('canvas')
  canvas.width = 128
  canvas.height = 256
  const ctx = canvas.getContext('2d')
  const grad = ctx.createLinearGradient(0, 0, 128, 256)
  grad.addColorStop(0, '#8f1f28')
  grad.addColorStop(1, '#4b0f18')
  ctx.fillStyle = grad
  ctx.beginPath()
  ctx.moveTo(0, 0); ctx.lineTo(128, 0); ctx.lineTo(128, 228); ctx.lineTo(64, 256); ctx.lineTo(0, 228)
  ctx.closePath(); ctx.fill()
  ctx.strokeStyle = 'rgba(255,210,130,0.85)'
  ctx.lineWidth = 4
  ctx.stroke()
  ctx.strokeStyle = 'rgba(255,220,150,0.55)'
  ctx.lineWidth = 2
  ctx.beginPath(); ctx.moveTo(64, 34); ctx.lineTo(96, 74); ctx.lineTo(64, 150); ctx.lineTo(32, 74); ctx.closePath(); ctx.stroke()
  ctx.beginPath(); ctx.moveTo(64, 52); ctx.lineTo(64, 132); ctx.stroke()
  ctx.beginPath(); ctx.moveTo(46, 92); ctx.lineTo(82, 92); ctx.stroke()
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

function addPlayerStyleHouse(batch, solid, glow, x, z, angle, rng) {
  const ry = angle
  const bodyH = 3.4 + rng() * 1.6
  const w = 5.2 + rng() * 2.2
  const d = 4.4 + rng() * 1.6
  const y = heightAt(x, z)

  batch.add(box(w, bodyH, d), '#c9b795', x, y + bodyH / 2, z, ry)
  batch.add(box(w * 0.94, 0.5, d * 0.94), '#8c7657', x, y + 0.25, z, ry)
  batch.add(box(w + 0.5, 0.3, d + 0.5), '#6a5843', x, y + bodyH - 0.15, z, ry)

  // Timber frame accents
  const fw = w * 0.5 + 0.05
  solid.add(box(0.22, bodyH * 0.9, 0.22), '#4a3826', x + Math.cos(ry) * (w / 2 - 0.2), y + bodyH / 2, z - Math.sin(ry) * (w / 2 - 0.2), ry)
  solid.add(box(0.22, bodyH * 0.9, 0.22), '#4a3826', x - Math.cos(ry) * (w / 2 - 0.2), y + bodyH / 2, z + Math.sin(ry) * (w / 2 - 0.2), ry)

  // Roof
  const roofH = 2.3 + rng() * 0.9
  const roof = new THREE.ConeGeometry(Math.max(w, d) * 0.78, roofH, 4, 1)
  batch.add(roof, rng() > 0.5 ? '#3d5a74' : '#6e3630', x, y + bodyH + roofH / 2 - 0.05, z, ry + Math.PI / 4)

  // Door (faces town center)
  const doorX = x + Math.sin(ry) * (d / 2 + 0.02)
  const doorZ = z + Math.cos(ry) * (d / 2 + 0.02)
  solid.add(box(1.0, 1.9, 0.12), '#4a3320', doorX, y + 0.95, doorZ, ry)

  // Windows
  const winY = y + bodyH * 0.6
  for (const side of [-1, 1]) {
    const wx = x + Math.cos(ry) * (w * 0.27) * side + Math.sin(ry) * (d / 2 + 0.04)
    const wz = z - Math.sin(ry) * (w * 0.27) * side + Math.cos(ry) * (d / 2 + 0.04)
    glow.add(box(0.85, 0.9, 0.08), '#ffd49a', wx, winY, wz, ry)
    glow.add(box(0.95, 0.12, 0.1), '#3d2c1a', wx, winY + 0.55, wz, ry)
    glow.add(box(0.95, 0.12, 0.1), '#3d2c1a', wx, winY - 0.55, wz, ry)
  }
  // Side window
  const sx = x + Math.cos(ry) * (w / 2 + 0.04)
  const sz = z - Math.sin(ry) * (w / 2 + 0.04)
  glow.add(box(0.08, 0.85, 0.75), '#ffd49a', sx, winY, sz, ry)

  // Chimney
  const chx = x - Math.cos(ry) * (w * 0.28)
  const chz = z + Math.sin(ry) * (w * 0.28)
  batch.add(box(0.7, 2.0, 0.7), '#7c6a58', chx, y + bodyH + roofH * 0.7, chz, ry)
}

function createTown() {
  const group = new THREE.Group()
  group.name = 'town'
  const batch = new GeoBatch()
  const solid = new GeoBatch()
  const glow = new GeoBatch()

  const groundY = heightAt(0, 0)
  const rng = mulberry32(4242)

  // Plaza platform + inlaid rings
  batch.add(new THREE.CylinderGeometry(22, 22.6, 0.5, 48), '#8f8d7f', 0, groundY - 0.05, 0)
  batch.add(new THREE.RingGeometry(14.6, 15.4, 64), '#a9a692', 0, groundY + 0.23, 0, 0, -Math.PI / 2)
  batch.add(new THREE.RingGeometry(8.2, 8.9, 64), '#a9a692', 0, groundY + 0.23, 0, 0, -Math.PI / 2)
  batch.add(new THREE.RingGeometry(21.1, 21.8, 64), '#b4ac8b', 0, groundY + 0.23, 0, 0, -Math.PI / 2)

  // Radial plaza spokes
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU
    batch.add(box(0.5, 0.06, 7.2), '#a9a692', Math.cos(a) * 11.6, groundY + 0.24, Math.sin(a) * 11.6, -a)
  }

  // Fountain
  const fx = 0, fz = 0
  batch.add(new THREE.CylinderGeometry(4.6, 5.0, 0.9, 16), '#9b9a8b', fx, groundY + 0.45, fz)
  batch.add(new THREE.CylinderGeometry(3.9, 4.0, 0.35, 16), '#6f8e96', fx, groundY + 0.92, fz)
  batch.add(new THREE.CylinderGeometry(1.15, 1.5, 3.6, 10), '#a7a495', fx, groundY + 2.4, fz)
  batch.add(new THREE.CylinderGeometry(2.2, 1.0, 0.55, 12), '#9b9a8b', fx, groundY + 4.3, fz)
  batch.add(new THREE.SphereGeometry(0.55, 8, 6), '#b9c6c4', fx, groundY + 4.9, fz)
  const water = new THREE.Mesh(
    new THREE.CylinderGeometry(3.8, 3.8, 0.1, 24),
    new THREE.MeshStandardMaterial({ color: '#67c8dd', emissive: '#1b6d82', emissiveIntensity: 0.7, transparent: true, opacity: 0.85, roughness: 0.2 })
  )
  water.position.set(fx, groundY + 1.12, fz)
  group.add(water)

  // Water jet glow
  const jet = new THREE.Mesh(
    new THREE.CylinderGeometry(0.07, 0.16, 2.1, 6),
    new THREE.MeshBasicMaterial({ color: '#b9f4ff', transparent: true, opacity: 0.55 })
  )
  jet.position.set(fx, groundY + 3.6, fz)
  group.add(jet)

  // Houses ring (leave the north for the gate)
  const houseAngles = [0.55, 1.15, 1.85, 2.55, 3.7, 4.45, 5.15, 5.75]
  for (let i = 0; i < houseAngles.length; i++) {
    const a = houseAngles[i]
    const r = 26.5 + rng() * 3.5
    const x = Math.cos(a) * r
    const z = Math.sin(a) * r
    addPlayerStyleHouse(batch, solid, glow, x, z, -a + Math.PI / 2 + (rng() - 0.5) * 0.2, rng)
  }

  // Town gate (north)
  const gz = -29
  const gy = heightAt(0, gz)
  for (const sx of [-1, 1]) {
    batch.add(box(1.5, 7.2, 1.5), '#9a988a', sx * 4.2, gy + 3.6, gz)
    batch.add(box(2.2, 0.7, 2.2), '#b0ad9c', sx * 4.2, gy + 0.35, gz)
    glow.add(new THREE.SphereGeometry(0.34, 8, 6), '#ffd49a', sx * 4.2, gy + 7.9, gz)
  }
  batch.add(box(11.0, 1.3, 1.8), '#8c8a7e', 0, gy + 7.6, gz)
  batch.add(box(9.0, 0.5, 2.1), '#a9a692', 0, gy + 8.35, gz)
  solid.add(box(2.0, 1.0, 0.6), '#4d4231', 0, gy + 6.7, gz)

  // Arch sign
  const signTex = makeSignTexture('TOWN OF BEGINNINGS', 'AINCRAD · FLOOR 1 · 10,000 PLAYERS')
  const sign = new THREE.Mesh(new THREE.PlaneGeometry(7.6, 2.08), new THREE.MeshBasicMaterial({ map: signTex, transparent: true }))
  sign.position.set(0, gy + 6.05, gz + 0.98)
  group.add(sign)
  const signBack = new THREE.Mesh(new THREE.PlaneGeometry(7.6, 2.08), new THREE.MeshBasicMaterial({ map: signTex, transparent: true }))
  signBack.position.set(0, gy + 6.05, gz - 0.98)
  signBack.rotation.y = Math.PI
  group.add(signBack)

  // Banners flanking the gate + plaza
  const bannerTex = makeBannerTexture()
  const bannerMat = new THREE.MeshStandardMaterial({ map: bannerTex, transparent: true, side: THREE.DoubleSide, roughness: 0.9, emissive: '#2a0a0e', emissiveIntensity: 0.35 })
  for (const x of [-9.5, 9.5, -4.2, 4.2]) {
    const b = new THREE.Mesh(new THREE.PlaneGeometry(1.35, 2.7), bannerMat)
    const z = x === -4.2 || x === 4.2 ? -25.5 : -26.2
    b.position.set(x, heightAt(x, z) + 5.6, z)
    b.rotation.y = 0
    group.add(b)
  }

  // Lantern posts around plaza
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU + 0.22
    const x = Math.cos(a) * 18.6
    const z = Math.sin(a) * 18.6
    const y = heightAt(x, z)
    batch.add(new THREE.CylinderGeometry(0.09, 0.12, 3.5, 6), '#5c5140', x, y + 1.75, z)
    batch.add(new THREE.SphereGeometry(0.3, 8, 6), '#ffd49a', x, y + 3.65, z)
    glow.add(new THREE.SphereGeometry(0.34, 8, 6), '#ffe3b0', x, y + 3.65, z)
  }

  // Flower beds and benches
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * TAU + 0.3
    const x = Math.cos(a) * 20
    const z = Math.sin(a) * 20
    const y = heightAt(x, z)
    batch.add(new THREE.CylinderGeometry(1.1, 1.0, 0.5, 8), '#6b5a42', x, y + 0.25, z)
    for (let f = 0; f < 6; f++) {
      const fa = rng() * TAU, fr = rng() * 0.75
      glow.add(new THREE.SphereGeometry(0.12, 5, 4), rng() > 0.5 ? '#ff8a8a' : '#ffe18a', x + Math.cos(fa) * fr, y + 0.62, z + Math.sin(fa) * fr)
    }
  }

  const stoneMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.88, metalness: 0.02 })
  const glowMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.5, emissive: '#ffb45e', emissiveIntensity: 1.3 })
  const stoneMesh = batch.mesh(stoneMat)
  const solidMesh = solid.mesh(stoneMat)
  const glowMesh = glow.mesh(glowMat)
  for (const m of [stoneMesh, solidMesh]) {
    if (m) { m.castShadow = true; m.receiveShadow = true; group.add(m) }
  }
  if (glowMesh) { glowMesh.castShadow = false; group.add(glowMesh) }

  // Colliders
  const colliders = [
    { x: 0, z: 0, r: 5.1 },
    { x: 0, z: gz, r: 2.2 }
  ]
  for (const a of houseAngles) {
    const r = 28
    colliders.push({ x: Math.cos(a) * r, z: Math.sin(a) * r, r: 4.3 })
  }
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU + 0.22
    colliders.push({ x: Math.cos(a) * 18.6, z: Math.sin(a) * 18.6, r: 0.4 })
  }
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * TAU + 0.3
    colliders.push({ x: Math.cos(a) * 20, z: Math.sin(a) * 20, r: 1.2 })
  }

  return { group, colliders, fountain: { x: 0, z: 0 } }
}

function createRuins() {
  const group = new THREE.Group()
  const batch = new GeoBatch()
  const glow = new GeoBatch()
  const rng = mulberry32(777)
  const cx = RUINS.x, cz = RUINS.z
  const baseY = heightAt(cx, cz)

  // Broken platform
  batch.add(new THREE.CylinderGeometry(15, 16, 1.1, 10), '#767268', cx, baseY - 0.2, cz)
  batch.add(new THREE.RingGeometry(9.4, 10.2, 32), '#5c584e', cx, baseY + 0.36, cz, 0, -Math.PI / 2)
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * TAU
    const r = 11.8
    const x = cx + Math.cos(a) * r, z = cz + Math.sin(a) * r
    batch.add(box(0.35, 0.1, 4.2), '#8d8778', x, baseY + 0.37, z, -a + Math.PI / 2)
  }

  // Standing and fallen pillars
  const pillars = [
    [-12, -4, 7, 0], [-9, 9, 5, 0.2], [7, 11, 8, -0.3], [12, -2, 4, 0.4],
    [3, -12, 6.5, 0.15], [-14, 5, 3, -0.2]
  ]
  for (const [dx, dz, h, tilt] of pillars) {
    const x = cx + dx, z = cz + dz
    const y = heightAt(x, z)
    batch.add(new THREE.CylinderGeometry(0.85, 1.0, h, 8), '#8a8478', x, y + h / 2, z, rng() * TAU, 0, tilt)
    batch.add(box(2.2, 0.45, 2.2), '#777267', x, y + 0.22, z, rng() * TAU)
    batch.add(box(2.4, 0.35, 2.4), '#8a8478', x + tilt * 0.4, y + h - 0.1, z, rng() * TAU)
  }
  // Fallen columns
  for (let i = 0; i < 4; i++) {
    const x = cx + (rng() - 0.5) * 22, z = cz + (rng() - 0.5) * 20
    const y = heightAt(x, z)
    batch.add(new THREE.CylinderGeometry(0.7, 0.7, 4 + rng() * 3, 7), '#7d786d', x, y + 0.7, z, rng() * TAU, Math.PI / 2, 0)
  }

  // Great broken arch
  const ax = cx, az = cz - 10
  const ay = heightAt(ax, az)
  for (const sx of [-1, 1]) {
    const px = ax + sx * 5
    batch.add(new THREE.CylinderGeometry(1.1, 1.35, 11, 8), '#7f7a6e', px, heightAt(px, az) + 5.5, az)
    glow.add(new THREE.BoxGeometry(0.4, 1.4, 0.2), '#67e2ff', px, heightAt(px, az) + 5.5, az + 1.2)
  }
  batch.add(box(13.5, 1.4, 2.2), '#6d685d', ax, ay + 11.4, az)
  batch.add(box(6.5, 1.2, 2.2), '#6d685d', ax + 2, ay + 12.5, az, 0.04)
  // Broken chunk gap: one side shorter
  glow.add(new THREE.TorusGeometry(7.6, 0.24, 6, 40), '#5ad8ff', ax, ay + 6.5, az, 0, Math.PI / 2)

  // Glowing rune circle
  glow.add(new THREE.RingGeometry(6.6, 6.9, 48), '#43d9ff', cx, baseY + 0.4, cz, 0, -Math.PI / 2)
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * TAU
    glow.add(box(0.18, 0.05, 1.5), '#7fe9ff', cx + Math.cos(a) * 8.1, baseY + 0.38, cz + Math.sin(a) * 8.1, -a)
  }

  const stoneMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.95, metalness: 0.02 })
  const glowMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.4, emissive: '#1d8ea8', emissiveIntensity: 1.4 })
  const m = batch.mesh(stoneMat)
  if (m) { m.castShadow = true; m.receiveShadow = true; group.add(m) }
  const g = glow.mesh(glowMat)
  if (g) group.add(g)

  const colliders = []
  for (const [dx, dz] of pillars) colliders.push({ x: cx + dx, z: cz + dz, r: 1.3 })
  for (const sx of [-1, 1]) colliders.push({ x: ax + sx * 5, z: az, r: 1.5 })

  return { group, colliders, center: { x: cx, z: cz } }
}

function grassTexture() {
  const canvas = document.createElement('canvas')
  canvas.width = 64
  canvas.height = 64
  const ctx = canvas.getContext('2d')
  ctx.clearRect(0, 0, 64, 64)
  for (let i = 0; i < 9; i++) {
    const x = 6 + Math.random() * 52
    const w = 2 + Math.random() * 3
    const h = 26 + Math.random() * 36
    const lean = (Math.random() - 0.5) * 16
    const grad = ctx.createLinearGradient(x, 64, x + lean, 64 - h)
    grad.addColorStop(0, 'rgba(34,63,28,1)')
    grad.addColorStop(0.55, 'rgba(83,124,53,1)')
    grad.addColorStop(1, 'rgba(150,185,96,1)')
    ctx.fillStyle = grad
    ctx.beginPath()
    ctx.moveTo(x, 64)
    ctx.quadraticCurveTo(x + lean * 0.3, 64 - h * 0.6, x + lean, 64 - h)
    ctx.quadraticCurveTo(x + lean * 0.3 + w, 64 - h * 0.6, x + w, 64)
    ctx.closePath()
    ctx.fill()
  }
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

function createVegetation(scene) {
  const rng = mulberry32(2024)
  const treeSpots = []
  const treeCount = 200
  for (let i = 0; i < treeCount * 4 && treeSpots.length < treeCount; i++) {
    const a = rng() * TAU
    const r = 42 + rng() * 140
    const x = Math.cos(a) * r
    const z = Math.sin(a) * r
    const dTown = Math.hypot(x, z)
    const dLake = Math.hypot(x - LAKE.x, z - LAKE.z)
    const dRuin = Math.hypot(x - RUINS.x, z - RUINS.z)
    if (dTown < 42 || dLake < LAKE.r + 5 || dRuin < 24) continue
    if (pathDistance(x, z) < 4) continue
    // Prefer the eastern forest, thinning in the plains.
    const forestBias = x > 35 ? 0.95 : x < -20 ? 0.45 : 0.3
    if (rng() > forestBias) continue
    const y = heightAt(x, z)
    if (y < WATER_Y + 1.4) continue
    treeSpots.push({ x, z, y, s: 0.8 + rng() * 0.9, rot: rng() * TAU })
  }

  const trunkGeo = new THREE.CylinderGeometry(0.22, 0.42, 4.2, 6)
  trunkGeo.translate(0, 2.1, 0)
  const trunkMat = new THREE.MeshStandardMaterial({ color: '#5a4128', roughness: 1, flatShading: true })
  const trunks = new THREE.InstancedMesh(trunkGeo, trunkMat, treeSpots.length)
  trunks.castShadow = true

  const foliageGeo = new THREE.IcosahedronGeometry(2.2, 0)
  const foliageMat = new THREE.MeshStandardMaterial({ roughness: 1, flatShading: true, vertexColors: false })
  const foliage = new THREE.InstancedMesh(foliageGeo, foliageMat, treeSpots.length * 2)
  foliage.castShadow = true

  const colliders = []
  const mtx = new THREE.Matrix4()
  const q = new THREE.Quaternion()
  const col = new THREE.Color()
  treeSpots.forEach((t, i) => {
    mtx.compose(new THREE.Vector3(t.x, t.y, t.z), q.setFromAxisAngle(new THREE.Vector3(0, 1, 0), t.rot), new THREE.Vector3(t.s, t.s, t.s))
    trunks.setMatrixAt(i, mtx)
    const base = new THREE.Color('#3d6b31').lerp(new THREE.Color('#6f9440'), rng())
    for (let k = 0; k < 2; k++) {
      const s = t.s * (k === 0 ? 1.0 : 0.72)
      const yOff = t.s * (k === 0 ? 4.6 : 6.4)
      mtx.compose(
        new THREE.Vector3(t.x + (k ? 0.5 * t.s : 0), t.y + yOff, t.z + (k ? -0.3 * t.s : 0)),
        q.setFromAxisAngle(new THREE.Vector3(0.2, 1, 0.1).normalize(), t.rot + k),
        new THREE.Vector3(s, s * 1.15, s)
      )
      foliage.setMatrixAt(i * 2 + k, mtx)
      foliage.setColorAt(i * 2 + k, col.copy(base).multiplyScalar(k ? 1.08 : 0.95))
    }
    colliders.push({ x: t.x, z: t.z, r: 0.65 * t.s })
  })
  trunks.instanceMatrix.needsUpdate = true
  foliage.instanceMatrix.needsUpdate = true
  if (foliage.instanceColor) foliage.instanceColor.needsUpdate = true
  scene.add(trunks, foliage)

  // Grass tufts
  const grassGeoA = new THREE.PlaneGeometry(0.7, 0.85)
  grassGeoA.translate(0, 0.42, 0)
  const grassGeoB = grassGeoA.clone()
  grassGeoB.rotateY(Math.PI / 2)
  const tuftGeo = mergeGeometries([grassGeoA, grassGeoB], false)
  const tex = grassTexture()
  const grassMat = new THREE.MeshStandardMaterial({
    map: tex, alphaTest: 0.42, transparent: false, side: THREE.DoubleSide,
    roughness: 1, color: '#a6c886'
  })
  grassMat.onBeforeCompile = shader => {
    shader.uniforms.uTime = { value: 0 }
    grassMat.userData.shader = shader
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nuniform float uTime;')
      .replace('#include <begin_vertex>', `
        #include <begin_vertex>
        vec3 instPos = vec3(instanceMatrix[3][0], instanceMatrix[3][1], instanceMatrix[3][2]);
        float wind = sin(uTime * 1.55 + instPos.x * 0.35 + instPos.z * 0.27) * 0.14
                   + sin(uTime * 2.7 + instPos.x * 0.9) * 0.05;
        transformed.x += wind * pow(max(position.y, 0.0), 1.5);
        transformed.z += wind * 0.5 * pow(max(position.y, 0.0), 1.5);
      `)
  }
  const grassCount = 3600
  const grass = new THREE.InstancedMesh(tuftGeo, grassMat, grassCount)
  grass.castShadow = false
  grass.receiveShadow = false
  const gq = new THREE.Quaternion()
  let gi = 0
  for (let i = 0; i < grassCount * 6 && gi < grassCount; i++) {
    const a = rng() * TAU
    const r = 12 + rng() * 155
    const x = Math.cos(a) * r
    const z = Math.sin(a) * r
    if (Math.hypot(x, z) < 7) continue
    if (pathDistance(x, z) < 1.6) continue
    if (Math.hypot(x - LAKE.x, z - LAKE.z) < LAKE.r - 4) continue
    const y = heightAt(x, z)
    if (y < WATER_Y + 0.3) continue
    if (Math.hypot(x - RUINS.x, z - RUINS.z) < 14) continue
    const s = 0.55 + rng() * 0.8
    mtx.compose(new THREE.Vector3(x, y, z), gq.setFromAxisAngle(new THREE.Vector3(0, 1, 0), rng() * TAU), new THREE.Vector3(s, s, s))
    grass.setMatrixAt(gi, mtx)
    gi++
  }
  grass.count = gi
  grass.instanceMatrix.needsUpdate = true
  grass.frustumCulled = false
  scene.add(grass)
  grass.userData.update = t => {
    const shader = grassMat.userData.shader
    if (shader) shader.uniforms.uTime.value = t
  }

  // Rocks
  const rockCount = 90
  const rockGeo = new THREE.DodecahedronGeometry(1, 0)
  const rockMat = new THREE.MeshStandardMaterial({ roughness: 1, flatShading: true })
  const rocks = new THREE.InstancedMesh(rockGeo, rockMat, rockCount)
  rocks.castShadow = true
  rocks.receiveShadow = true
  let ri = 0
  for (let i = 0; i < rockCount * 5 && ri < rockCount; i++) {
    const a = rng() * TAU
    const r = 20 + rng() * 156
    const x = Math.cos(a) * r
    const z = Math.sin(a) * r
    if (Math.hypot(x, z) < 25 || pathDistance(x, z) < 3) continue
    if (Math.hypot(x - LAKE.x, z - LAKE.z) < LAKE.r) continue
    if (Math.hypot(x - RUINS.x, z - RUINS.z) < 22) continue
    const s = 0.6 + rng() * 2.6
    const y = heightAt(x, z)
    mtx.compose(
      new THREE.Vector3(x, y + s * 0.35, z),
      gq.setFromEuler(new THREE.Euler(rng() * 0.4, rng() * TAU, rng() * 0.4)),
      new THREE.Vector3(s, s * (0.6 + rng() * 0.5), s)
    )
    rocks.setMatrixAt(ri, mtx)
    rocks.setColorAt(ri, col.set('#8a8a80').multiplyScalar(0.8 + rng() * 0.35))
    colliders.push({ x, z, r: s * 0.8 })
    ri++
  }
  rocks.count = ri
  rocks.instanceMatrix.needsUpdate = true
  if (rocks.instanceColor) rocks.instanceColor.needsUpdate = true
  scene.add(rocks)

  return { colliders, update: t => grass.userData.update(t) }
}

export function createWorld(scene) {
  const town = createTown()
  const ruins = createRuins()
  scene.add(town.group, ruins.group)

  const vegetation = createVegetation(scene)

  // Scattered distant pine silhouettes on the mountain ring for depth.
  const rng = mulberry32(999)
  const farTrees = new THREE.Group()
  const trunkMat = new THREE.MeshStandardMaterial({ color: '#3c4a38', roughness: 1 })
  const leafMat = new THREE.MeshStandardMaterial({ color: '#2f4a33', roughness: 1, flatShading: true })
  for (let i = 0; i < 70; i++) {
    const a = rng() * TAU
    const r = 148 + rng() * 55
    const x = Math.cos(a) * r
    const z = Math.sin(a) * r
    const y = heightAt(x, z)
    if (y < 5) continue
    const s = 0.8 + rng() * 1.4
    const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.35, 3.4, 5), trunkMat)
    trunk.position.set(x, y + 1.7 * s, z)
    trunk.scale.setScalar(s)
    const leaves = new THREE.Mesh(new THREE.ConeGeometry(2.0, 6.5, 6), leafMat)
    leaves.position.set(x, y + 5.4 * s, z)
    leaves.scale.setScalar(s)
    farTrees.add(trunk, leaves)
  }
  scene.add(farTrees)

  return {
    town,
    ruins,
    colliders: [...town.colliders, ...ruins.colliders, ...vegetation.colliders],
    update: t => vegetation.update(t)
  }
}

// Tiny procedural audio engine: ambience, music and combat SFX with no assets.
export class AudioEngine {
  constructor() {
    this.ctx = null
    this.master = null
    this.musicGain = null
    this.sfxGain = null
    this.started = false
    this.musicTimer = 0
    this.step = 0
  }

  start() {
    if (this.started) return
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return
    this.ctx = new AC()
    this.master = this.ctx.createGain()
    this.master.gain.value = 0.55
    this.master.connect(this.ctx.destination)

    this.musicGain = this.ctx.createGain()
    this.musicGain.gain.value = 0.16
    this.musicGain.connect(this.master)
    this.sfxGain = this.ctx.createGain()
    this.sfxGain.gain.value = 0.7
    this.sfxGain.connect(this.master)

    this.started = true
    this.ctx.resume()
    this.startWind()
    this.startPad()
    this.scheduleMusic()
  }

  startWind() {
    const ctx = this.ctx
    const len = ctx.sampleRate * 4
    const buffer = ctx.createBuffer(1, len, ctx.sampleRate)
    const data = buffer.getChannelData(0)
    let last = 0
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1
      last = last * 0.985 + white * 0.015
      data[i] = last * 2.2
    }
    const src = ctx.createBufferSource()
    src.buffer = buffer
    src.loop = true
    const filter = ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.value = 480
    const gain = ctx.createGain()
    gain.gain.value = 0.05
    const lfo = ctx.createOscillator()
    lfo.frequency.value = 0.06
    const lfoGain = ctx.createGain()
    lfoGain.gain.value = 0.025
    lfo.connect(lfoGain).connect(gain.gain)
    src.connect(filter).connect(gain).connect(this.master)
    src.start()
    lfo.start()
  }

  startPad() {
    const ctx = this.ctx
    const notes = [110, 164.81, 220, 329.63]
    this.padOscs = notes.map((f, i) => {
      const o = ctx.createOscillator()
      o.type = i % 2 ? 'triangle' : 'sine'
      o.frequency.value = f
      o.detune.value = (i - 1.5) * 6
      const g = ctx.createGain()
      g.gain.value = 0.018
      const filter = ctx.createBiquadFilter()
      filter.type = 'lowpass'
      filter.frequency.value = 700
      o.connect(filter).connect(g).connect(this.musicGain)
      o.start()
      return { o, g, base: f }
    })
    // Slow shimmering chord movement.
    setInterval(() => {
      if (!this.ctx) return
      const t = this.ctx.currentTime
      const roots = [110, 98, 123.47, 87.31]
      const root = roots[Math.floor(Math.random() * roots.length)]
      const ratios = [1, 1.5, 2, 2.997]
      this.padOscs.forEach((p, i) => {
        p.o.frequency.setTargetAtTime(root * ratios[i], t, 3.5)
      })
    }, 14000)
  }

  scheduleMusic() {
    const patterns = [
      [0, 3, 5, 7, 5, 3, 7, 10],
      [0, 2, 3, 7, 5, 3, 2, 0],
      [0, 5, 7, 12, 10, 7, 5, 3]
    ]
    const scale = [220, 246.94, 293.66, 329.63, 392, 440, 493.88, 587.33]
    const play = () => {
      if (!this.ctx) return
      const pattern = patterns[this.step % patterns.length]
      const noteIdx = pattern[Math.floor(Math.random() * pattern.length)]
      const freq = scale[noteIdx] * 2
      if (Math.random() < 0.72) this.pluck(freq, 0.045, 2.6)
      if (this.step % 4 === 0) this.pluck(scale[noteIdx] * 0.5, 0.05, 4)
      this.step++
      this.musicTimer = setTimeout(play, 780 + Math.random() * 500)
    }
    this.musicTimer = setTimeout(play, 2000)
  }

  pluck(freq, vol = 0.05, decay = 2.5) {
    if (!this.ctx) return
    const ctx = this.ctx
    const t = ctx.currentTime
    const o = ctx.createOscillator()
    o.type = 'triangle'
    o.frequency.value = freq
    const g = ctx.createGain()
    g.gain.setValueAtTime(0, t)
    g.gain.linearRampToValueAtTime(vol, t + 0.01)
    g.gain.exponentialRampToValueAtTime(0.0001, t + decay)
    const filter = ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.value = 2200
    o.connect(filter).connect(g).connect(this.musicGain)
    o.start(t)
    o.stop(t + decay + 0.1)
  }

  noiseBurst({ dur = 0.18, vol = 0.35, type = 'highpass', freq = 900, freqEnd = 2600, q = 0.8 } = {}) {
    if (!this.ctx) return
    const ctx = this.ctx
    const t = ctx.currentTime
    const len = Math.ceil(ctx.sampleRate * dur)
    const buffer = ctx.createBuffer(1, len, ctx.sampleRate)
    const data = buffer.getChannelData(0)
    for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / len)
    const src = ctx.createBufferSource()
    src.buffer = buffer
    const filter = ctx.createBiquadFilter()
    filter.type = type
    filter.frequency.setValueAtTime(freq, t)
    filter.frequency.exponentialRampToValueAtTime(freqEnd, t + dur)
    filter.Q.value = q
    const g = ctx.createGain()
    g.gain.setValueAtTime(vol, t)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    src.connect(filter).connect(g).connect(this.sfxGain)
    src.start(t)
  }

  tone({ freq = 440, dur = 0.2, vol = 0.2, type = 'sine', slide = 0, delay = 0 } = {}) {
    if (!this.ctx) return
    const ctx = this.ctx
    const t = ctx.currentTime + delay
    const o = ctx.createOscillator()
    o.type = type
    o.frequency.setValueAtTime(freq, t)
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur)
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(vol, t + 0.012)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    o.connect(g).connect(this.sfxGain)
    o.start(t)
    o.stop(t + dur + 0.05)
  }

  swing(heavy = false) {
    this.noiseBurst({ dur: heavy ? 0.3 : 0.16, vol: heavy ? 0.42 : 0.26, freq: 600, freqEnd: heavy ? 3400 : 2600, q: 1.4 })
    if (heavy) this.tone({ freq: 90, dur: 0.2, vol: 0.14, type: 'sawtooth', slide: -40 })
  }

  hit(crit = false) {
    this.noiseBurst({ dur: 0.12, vol: 0.4, type: 'bandpass', freq: 1800, freqEnd: 700, q: 1.1 })
    this.tone({ freq: crit ? 320 : 180, dur: 0.16, vol: 0.24, type: 'square', slide: -100 })
    if (crit) this.tone({ freq: 880, dur: 0.12, vol: 0.08, type: 'triangle', slide: 300 })
  }

  hurt() {
    this.tone({ freq: 140, dur: 0.3, vol: 0.26, type: 'sawtooth', slide: -70 })
    this.noiseBurst({ dur: 0.22, vol: 0.28, freq: 500, freqEnd: 180 })
  }

  dodge() {
    this.noiseBurst({ dur: 0.3, vol: 0.2, freq: 300, freqEnd: 1400 })
  }

  levelUp() {
    const notes = [523.25, 659.25, 783.99, 1046.5, 1318.5]
    notes.forEach((f, i) => this.tone({ freq: f, dur: 0.5, vol: 0.12, type: 'triangle', delay: i * 0.09 }))
    this.tone({ freq: 261.63, dur: 1.2, vol: 0.06, type: 'sine', delay: 0.1 })
  }

  questComplete() {
    ;[392, 523.25, 659.25].forEach((f, i) => this.tone({ freq: f, dur: 0.45, vol: 0.1, type: 'triangle', delay: i * 0.11 }))
  }

  potion() {
    this.tone({ freq: 660, dur: 0.16, vol: 0.12, type: 'sine', slide: 320 })
    this.tone({ freq: 990, dur: 0.3, vol: 0.08, type: 'sine', slide: 220, delay: 0.12 })
  }

  ui() {
    this.tone({ freq: 780, dur: 0.06, vol: 0.07, type: 'square' })
  }

  death() {
    this.tone({ freq: 220, dur: 1.6, vol: 0.2, type: 'sawtooth', slide: -170 })
    this.tone({ freq: 110, dur: 2.0, vol: 0.12, type: 'sine', slide: -60 })
  }

  enemyDie() {
    this.noiseBurst({ dur: 0.45, vol: 0.25, type: 'lowpass', freq: 900, freqEnd: 120 })
    this.tone({ freq: 130, dur: 0.4, vol: 0.14, type: 'triangle', slide: -80 })
  }
}

import * as THREE from 'three'
import { rand, TAU } from './utils.js'

function softTexture(inner = 'rgba(255,255,255,0.9)', outer = 'rgba(255,255,255,0)') {
  const c = document.createElement('canvas')
  c.width = c.height = 64
  const ctx = c.getContext('2d')
  const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 32)
  g.addColorStop(0, inner)
  g.addColorStop(0.35, inner.replace(/[\d.]+\)$/, '0.55)'))
  g.addColorStop(1, outer)
  ctx.fillStyle = g
  ctx.fillRect(0, 0, 64, 64)
  return new THREE.CanvasTexture(c)
}

export class Effects {
  constructor(scene, camera) {
    this.scene = scene
    this.camera = camera
    this.time = 0
    this.slashes = []
    this.bursts = []
    this.dusts = []
    this.waves = []
    this.soft = softTexture()

    const slashGeo = new THREE.RingGeometry(1.05, 1.85, 26, 1, -0.85, 1.7)
    for (let i = 0; i < 8; i++) {
      const mat = new THREE.MeshBasicMaterial({
        color: '#bff4ff', transparent: true, opacity: 0, side: THREE.DoubleSide,
        blending: THREE.AdditiveBlending, depthWrite: false
      })
      const mesh = new THREE.Mesh(slashGeo, mat)
      mesh.visible = false
      mesh.renderOrder = 5
      scene.add(mesh)
      this.slashes.push({ mesh, life: 0, max: 0.28, spin: 0 })
    }

    const burstGeo = new THREE.BufferGeometry()
    const maxP = 34
    burstGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(maxP * 3), 3))
    for (let i = 0; i < 10; i++) {
      const mat = new THREE.PointsMaterial({
        color: '#fff3c4', size: 0.16, transparent: true, opacity: 0,
        blending: THREE.AdditiveBlending, depthWrite: false, map: this.soft, alphaTest: 0.01
      })
      const pts = new THREE.Points(burstGeo.clone(), mat)
      pts.visible = false
      pts.frustumCulled = false
      pts.renderOrder = 6
      scene.add(pts)
      this.bursts.push({ pts, vels: [], life: 0, max: 0.5, count: maxP })
    }

    const dustGeo = new THREE.PlaneGeometry(1, 1)
    for (let i = 0; i < 16; i++) {
      const mat = new THREE.SpriteMaterial({ map: this.soft, color: '#cbbfa8', transparent: true, opacity: 0, depthWrite: false })
      const sp = new THREE.Sprite(mat)
      sp.visible = false
      scene.add(sp)
      this.dusts.push({ sp, life: 0, max: 0.7, vel: new THREE.Vector3(), grow: 1 })
    }

    const waveGeo = new THREE.RingGeometry(0.9, 1.05, 48)
    for (let i = 0; i < 6; i++) {
      const mat = new THREE.MeshBasicMaterial({
        color: '#9be8ff', transparent: true, opacity: 0, side: THREE.DoubleSide,
        blending: THREE.AdditiveBlending, depthWrite: false
      })
      const mesh = new THREE.Mesh(waveGeo, mat)
      mesh.rotation.x = -Math.PI / 2
      mesh.visible = false
      scene.add(mesh)
      this.waves.push({ mesh, life: 0, max: 0.5, maxR: 6 })
    }

    // Lock-on indicator
    this.lock = new THREE.Group()
    const lockRing = new THREE.Mesh(
      new THREE.RingGeometry(0.62, 0.7, 28),
      new THREE.MeshBasicMaterial({ color: '#ffb347', transparent: true, opacity: 0.9, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false })
    )
    lockRing.rotation.x = -Math.PI / 2
    this.lock.add(lockRing)
    const dia = new THREE.Mesh(
      new THREE.OctahedronGeometry(0.12, 0),
      new THREE.MeshBasicMaterial({ color: '#ffd28a', transparent: true, opacity: 0.95 })
    )
    dia.position.y = 0.7
    this.lock.add(dia)
    this.lock.visible = false
    scene.add(this.lock)
    this.lockTarget = null

    // Player aura ring (used on level-up / skills)
    this.aura = new THREE.Mesh(
      new THREE.RingGeometry(1.0, 1.12, 48),
      new THREE.MeshBasicMaterial({ color: '#8fffd0', transparent: true, opacity: 0, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false })
    )
    this.aura.rotation.x = -Math.PI / 2
    this.aura.visible = false
    scene.add(this.aura)
    this.auraLife = 0
  }

  slash(pos, yaw, color = '#bff4ff', size = 1, tilt = 0, flip = false) {
    const s = this.slashes.find(x => x.life <= 0) || this.slashes[0]
    s.mesh.position.copy(pos)
    s.mesh.rotation.set(-Math.PI / 2 + tilt, yaw, flip ? Math.PI : 0)
    s.mesh.scale.setScalar(size)
    s.mesh.material.color.set(color)
    s.mesh.material.opacity = 0.95
    s.mesh.visible = true
    s.life = s.max = 0.26
    s.spin = (flip ? 1 : -1) * 7
  }

  burst(pos, color = '#ffe9ab', count = 22, speed = 7, size = 0.16) {
    const b = this.bursts.find(x => x.life <= 0) || this.bursts[0]
    const attr = b.pts.geometry.getAttribute('position')
    b.vels = []
    for (let i = 0; i < b.count; i++) {
      attr.setXYZ(i, pos.x, pos.y, pos.z)
      const v = new THREE.Vector3(rand(-1, 1), rand(-0.2, 1), rand(-1, 1)).normalize().multiplyScalar(rand(speed * 0.3, speed))
      b.vels.push(v)
    }
    attr.needsUpdate = true
    b.pts.material.color.set(color)
    b.pts.material.size = size
    b.pts.material.opacity = 1
    b.pts.visible = true
    b.life = b.max = 0.55
  }

  dust(pos, count = 3, color = '#cbbfa8', spread = 0.7) {
    let spawned = 0
    for (const d of this.dusts) {
      if (d.life > 0) continue
      d.sp.position.set(pos.x + rand(-spread, spread), pos.y + rand(0.05, 0.25), pos.z + rand(-spread, spread))
      d.sp.material.color.set(color)
      d.sp.material.opacity = 0.55
      d.sp.scale.setScalar(rand(0.3, 0.7))
      d.vel.set(rand(-0.6, 0.6), rand(0.4, 1.1), rand(-0.6, 0.6))
      d.sp.visible = true
      d.life = d.max = rand(0.5, 0.9)
      d.grow = rand(1.2, 2.4)
      if (++spawned >= count) break
    }
  }

  wave(pos, color = '#9be8ff', maxR = 6, dur = 0.5) {
    const w = this.waves.find(x => x.life <= 0) || this.waves[0]
    w.mesh.position.set(pos.x, pos.y + 0.12, pos.z)
    w.mesh.material.color.set(color)
    w.mesh.material.opacity = 0.85
    w.mesh.scale.setScalar(0.4)
    w.mesh.visible = true
    w.life = w.max = dur
    w.maxR = maxR
  }

  auraPulse(pos, color = '#8fffd0', scale = 3.2) {
    this.aura.position.set(pos.x, pos.y + 0.1, pos.z)
    this.aura.material.color.set(color)
    this.aura.scale.setScalar(0.6)
    this.aura.userData.maxScale = scale
    this.aura.material.opacity = 0.85
    this.aura.visible = true
    this.auraLife = 0.7
  }

  setLock(target) {
    this.lockTarget = target
    this.lock.visible = !!target
  }

  update(dt) {
    this.time += dt
    for (const s of this.slashes) {
      if (!s.mesh.visible) continue
      s.life -= dt
      if (s.life <= 0) { s.mesh.visible = false; s.mesh.material.opacity = 0; continue }
      const p = 1 - s.life / s.max
      s.mesh.material.opacity = (1 - p) * 0.95
      s.mesh.rotation.z += s.spin * dt
      s.mesh.scale.multiplyScalar(1 + dt * 2.2)
    }
    for (const b of this.bursts) {
      if (!b.pts.visible) continue
      b.life -= dt
      if (b.life <= 0) { b.pts.visible = false; continue }
      const attr = b.pts.geometry.getAttribute('position')
      for (let i = 0; i < b.count; i++) {
        const v = b.vels[i]
        v.y -= 13 * dt
        v.multiplyScalar(1 - 1.6 * dt)
        attr.setXYZ(i, attr.getX(i) + v.x * dt, attr.getY(i) + v.y * dt, attr.getZ(i) + v.z * dt)
      }
      attr.needsUpdate = true
      b.pts.material.opacity = Math.min(1, b.life / b.max * 1.6)
    }
    for (const d of this.dusts) {
      if (!d.sp.visible) continue
      d.life -= dt
      if (d.life <= 0) { d.sp.visible = false; continue }
      d.sp.position.addScaledVector(d.vel, dt)
      d.sp.scale.multiplyScalar(1 + d.grow * dt)
      d.sp.material.opacity = (d.life / d.max) * 0.5
    }
    for (const w of this.waves) {
      if (!w.mesh.visible) continue
      w.life -= dt
      if (w.life <= 0) { w.mesh.visible = false; continue }
      const p = 1 - w.life / w.max
      w.mesh.scale.setScalar(0.4 + p * w.maxR)
      w.mesh.material.opacity = (1 - p) * 0.8
    }
    if (this.auraLife > 0) {
      this.auraLife -= dt
      const p = 1 - this.auraLife / 0.7
      this.aura.material.opacity = (1 - p) * 0.85
      this.aura.scale.setScalar(0.6 + p * (this.aura.userData.maxScale || 3))
      if (this.auraLife <= 0) this.aura.visible = false
    }
    if (this.lockTarget && this.lockTarget.alive) {
      this.lock.position.set(this.lockTarget.pos.x, this.lockTarget.pos.y + 0.05, this.lockTarget.pos.z)
      this.lock.rotation.y += dt * 1.6
      this.lock.children[1].position.y = 0.68 + Math.sin(this.time * 3) * 0.1
      this.lock.visible = true
    } else {
      this.lock.visible = false
    }
  }
}
